INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2890640', 'Battle of Abrolhos', 'The naval Battle of the Abrolhos took place on 12 September 1631 off the coast of Pernambuco, Brazil, during the Eighty Years'' War. A joint Spanish-Portuguese fleet under admiral Antonio de Oquendo defeated the Dutch after a six-hour naval battle.', 1631, 9, 12, NULL, NULL, NULL, 'day', '12 September 1631', 45, 'https://en.wikipedia.org/wiki/Battle_of_Abrolhos'),
  ('Q932845', 'First Battle of Salvador', 'The siege of Salvador was a siege that took place between April and May 1638, during the Dutch–Portuguese War and Eighty Years'' War. The governor of the Dutch colony in Brazil, John Maurice, Prince of Nassau-Siegen, commanding the army of the Dutch West India Company, with vastly superior forces and a supporting fleet under Johan van der Mast, put the city of Salvador under siege.', 1638, 5, NULL, 1638, 5, 18, 'month', 'May 1638 – 18 May 1638', 39, 'https://en.wikipedia.org/wiki/Siege_of_Salvador_(1638)'),
  ('Q3406431', 'Acclamation of Amador Bueno', 'The acclamation of Amador Bueno (Portuguese: Aclamação de Amador Bueno), was an abortive revolt orchestrated primarily by Spanish colonists in São Paulo dos Campos de Piratininga in 1641, shortly after the royal acclamation of John IV. It is considered the first nativist movement or the first gesture of autonomy in Colonial Brazil and, not coincidentally, took place in São Paulo, which at the time had limited contact with Portugal and extensive miscegenation between Portuguese, indigenous peoples, and foreigners.', 1641, NULL, NULL, NULL, NULL, NULL, 'year', '1641', 39, 'https://en.wikipedia.org/wiki/Acclamation_of_Amador_Bueno'),
  ('Q10303008', 'Insurrection of Pernambuco', 'The Insurrection of Pernambuco (Portuguese: Insurreição Pernambucana), also known as the War of the Divine Light (Guerra da Luz Divina), was a movement against Dutch rule in the Captaincy of Pernambuco. The revolution occurred in the course of the second Dutch invasion during the Dutch–Portuguese War and resulted in the expulsion of the Dutch from the northeast region of Brazil, followed by the reclamation of the territory by the Kingdom of Portugal.', 1645, 5, 15, 1654, 1, 26, 'day', '15 May 1645 – 26 January 1654', 41, 'https://en.wikipedia.org/wiki/Insurrection_of_Pernambuco'),
  ('Q3052957', 'Emboabas'' War', 'The War of the Emboabas (Guerra dos Emboabas, lit. “war of the newcomers”) was an internal conflict in colonial Brazil fought between 1707 and 1709 over control of newly discovered gold fields in the interior of the Captaincy of São Vicente.', 1707, NULL, NULL, NULL, NULL, NULL, 'year', '1707', 45, 'https://en.wikipedia.org/wiki/War_of_the_Emboabas'),
  ('Q3119045', 'Mascate War', 'The War of the Mascates might be more accurately called an insurrection; the main events occurred in and around Recife, Pernambuco during 1710 and 1711. Some consider the underlying causes lasted for two centuries.', 1710, NULL, NULL, 1711, NULL, NULL, 'year', '1710–1711', 41, 'https://en.wikipedia.org/wiki/War_of_the_Mascates'),
  ('Q820269', 'Battle of Rio de Janeiro', 'The Battle of Rio de Janeiro was a raid in September 1711 on the port of Rio de Janeiro in the War of Spanish Succession by a French squadron under René Duguay-Trouin. The Portuguese defenders, including the city''s governor and an admiral of the fleet anchored there, were unable to put up effective resistance in spite of numerical advantages and the city had to pay a ransom to avoid destruction of its defences.', 1711, 9, 12, 1711, 9, 22, 'day', '12 September 1711 – 22 September 1711', 47, 'https://en.wikipedia.org/wiki/Battle_of_Rio_de_Janeiro'),
  ('Q4204142', 'Spanish–Portuguese War of 1776-1777', 'The Spanish-Portuguese War, also known as the Second Cevallos expedition, was fought between 1776 and 1777 over the border between Spanish and Portuguese South America.', 1776, 2, NULL, 1777, 2, 24, 'month', 'February 1776 – 24 February 1777', 45, 'https://en.wikipedia.org/wiki/Spanish%E2%80%93Portuguese_War_(1776%E2%80%931777)'),
  ('Q2558843', 'Minas Gerais Conspiracy', 'The Inconfidência Mineira (Portuguese pronunciation: [ĩkõfiˈdẽsiɐ miˈnejɾɐ]; "Minas Gerais Conspiracy") was an unsuccessful separatist movement in Colonial Brazil in 1789. It was the result of a confluence of external and internal causes.', 1789, NULL, NULL, NULL, NULL, NULL, 'year', '1789', 50, 'https://en.wikipedia.org/wiki/Inconfid%C3%AAncia_Mineira'),
  ('Q24728', 'Siege of Salvador', 'The siege of Salvador occurred during the Brazilian War of Independence, during which the newly formed Brazilian army, under the command of French general Pierre Labatut, attempted to capture the city of Salvador in Bahia from its Portuguese defenders. The siege lasted from 2 March 1822 until 2 July 1823, finally ending when the Portuguese commander, Madeira de Melo, surrendered his forces to the Brazilians.', 1822, 3, 2, 1823, 7, 2, 'day', '2 March 1822 – 2 July 1823', 41, 'https://en.wikipedia.org/wiki/Siege_of_Salvador_(1822%E2%80%931823)'),
  ('Q1548600', 'Independence of Brazil', 'The independence of Brazil (Portuguese: independência do Brasil) began after a series of political and military events that led the Kingdom of Brazil to separate from the United Kingdom of Portugal, Brazil and the Algarves. It is celebrated on 7 September, the date in 1822 when prince regent Pedro of Braganza, beside the Ipiranga brook, declared independence from Portugal – a declaration that became known as the Cry of Ipiranga.', 1822, 9, 7, NULL, NULL, NULL, 'day', '7 September 1822', 63, 'https://en.wikipedia.org/wiki/Independence_of_Brazil'),
  ('Q2890728', 'Battle of 4 May', 'The Battle of 4 May was fought in open sea near Salvador, Bahia, on 4 May 1823, between the Imperial Brazilian Navy, under the command of British admiral Thomas Cochrane, and the Portuguese Navy during the Brazilian War of Independence.', 1823, 5, 4, NULL, NULL, NULL, 'day', '4 May 1823', 37, 'https://en.wikipedia.org/wiki/Battle_of_4_May'),
  ('Q2480544', 'Battle of Ituzaingó', 'The Battle of Ituzaingó, also known as the Battle of Passo do Rosário, was a pitched battle fought in the vicinity of the Santa Maria River, in a valley of small hills where a stream divided the valley into two. After a two-year series of continuous sundry skirmishes in the Banda Oriental (present-day Uruguay and Rio Grande do Sul) and along the border of this region with Brazil, the advancing Argentine Army (including Orientals) engaged in combat with the Imperial Brazilian Army.', 1827, 2, 20, NULL, NULL, NULL, 'day', '20 February 1827', 41, 'https://en.wikipedia.org/wiki/Battle_of_Ituzaing%C3%B3'),
  ('Q2590269', 'Cabanagem', 'The Cabanagem (Portuguese pronunciation: [kabaˈnaʒẽj]; 1835–1840) was a popular revolution and pro-separatist movement that occurred in the then province of Grão-Pará, Empire of Brazil. Among the causes for this revolt were the extreme poverty of the Paraense people, oppression by the Empire of Brazil, and the political irrelevance to which the province was relegated after the independence of Brazil.', 1835, NULL, NULL, NULL, NULL, NULL, 'year', '1835', 50, 'https://en.wikipedia.org/wiki/Cabanagem'),
  ('Q6745211', 'Malê Revolt', 'The Malê revolt (Portuguese: Revolta dos Malês, pronounced [ʁɛˈvɔwtɐ duz maˈle(j)s], [ʁeˈvɔwtɐ duz mɐˈle(j)s]) was a Muslim slave rebellion that broke out during the regency period in the Empire of Brazil. On a Sunday during Ramadan in January 1835, in the city of Salvador, a group of enslaved African Muslims and freedmen, inspired by Muslim teachers, rose up against the government.', 1835, 1, NULL, NULL, NULL, NULL, 'month', 'January 1835', 47, 'https://en.wikipedia.org/wiki/Mal%C3%AA_revolt'),
  ('Q2880458', 'Balaiada', 'The Balaiada was a social revolt between 1838 and 1841 in the interior of the Province of Maranhão, Brazil.', 1837, NULL, NULL, 1841, NULL, NULL, 'year', '1837–1841', 43, 'https://en.wikipedia.org/wiki/Balaiada'),
  ('Q4403481', 'Sabinada', 'The Sabinada (1837–1838) was a revolt by military officer Francisco Sabino that occurred in Brazil''s Bahia province between 6 November 1837 and 16 March 1838. The rebels proposed the existence of a Bahian Republic of a transitory nature until Emperor Dom Pedro II reached the age of majority.', 1837, 11, 6, 1838, 3, 16, 'day', '6 November 1837 – 16 March 1838', 41, 'https://en.wikipedia.org/wiki/Sabinada'),
  ('Q2635125', 'Praieira revolt', 'The Praieira revolt, also known as the Beach rebellion, was a movement in the Pernambuco province of the Empire of Brazil that lasted from 1848 to 1849. The revolt, influenced by revolutions taking place in Europe, was due in part to unresolved conflicts left over from the Regency period and local resistance to the consolidation of the Empire of Brazil that had been proclaimed in 1822.', 1848, 11, 6, NULL, NULL, NULL, 'day', '6 November 1848', 43, 'https://en.wikipedia.org/wiki/Praieira_revolt'),
  ('Q2500742', 'Revolta da Armada', 'The Brazilian Naval Revolts (Portuguese: Revoltas da Armada, lit. ''Navy''s Revolt'') were armed mutinies promoted mainly by admirals Custódio José de Melo and Saldanha da Gama and their fleet of rebel Brazilian navy ships against the claimed unconstitutional staying in power of president Floriano Peixoto. The revolts had a number of causes: "personal animosities in the ruling elite; friction in federal-state relations and between the president and Congress; militarism; government extravagance; army navy rivalry; and some lingering monarchical sentiments following the overthrow of the empire…', 1893, NULL, NULL, NULL, NULL, NULL, 'year', '1893', 48, 'https://en.wikipedia.org/wiki/Brazilian_Naval_Revolts'),
  ('Q2606574', 'Acre War', 'The Acre War, known in Brazil as Acrean Revolution (Portuguese: Revolução Acreana) and in Spanish as Guerra del Acre ("War of the Acre") was a border conflict between Bolivia and the First Brazilian Republic over the Acre Region, which was rich in rubber and gold deposits. The conflict had two phases between 1899 and 1903, and ended with an Acrean victory and the subsequent Treaty of Petrópolis, which ceded Acre to Brazil.', 1899, NULL, NULL, 1903, NULL, NULL, 'year', '1899–1903', 56, 'https://en.wikipedia.org/wiki/Acre_War'),
  ('Q2667511', 'Contestado War', 'The Contestado War (Portuguese: Guerra do Contestado), broadly speaking, was a guerrilla war for land between settlers and landowners, the latter supported by the Brazilian state''s police and military forces, that lasted from October 1912 to August 1916. It was fought in an inland southern region of the country, rich in wood and yerba mate, that was called Contestado because it was contested by the states of Paraná and Santa Catarina as well as Argentina.', 1912, NULL, NULL, NULL, NULL, NULL, 'year', '1912', 43, 'https://en.wikipedia.org/wiki/Contestado_War'),
  ('Q1112912', 'Coluna Prestes', 'The Coluna Prestes, also known as the Coluna Miguel Costa-Prestes or, formally, the 1st Revolutionary Division, was a Brazilian political-military movement associated with Tenentism that operated between 1924 and 1927. It emerged from dissatisfaction with the government of Artur Bernardes and with the oligarchic order of the First Brazilian Republic, especially the political arrangements commonly associated with the café com leite system.', 1921, NULL, NULL, 1927, NULL, NULL, 'decade', '1920s – 1927', 41, 'https://en.wikipedia.org/wiki/Coluna_Prestes'),
  ('Q2745716', 'Paulista Revolution', 'The São Paulo Revolt of 1924 (Portuguese: Revolta Paulista), also called the Revolution of 1924 (Revolução de 1924), Movement of 1924 (Movimento de 1924) or Second 5th of July (Segundo 5 de Julho) was a Brazilian conflict with characteristics of a civil war, initiated by tenentist rebels to overthrow the government of president Artur Bernardes. From the city of São Paulo on 5 July, the revolt expanded to the interior of the state and inspired other uprisings across Brazil.', 1924, NULL, NULL, 1924, 7, 28, 'year', '1924', 39, 'https://en.wikipedia.org/wiki/S%C3%A3o_Paulo_Revolt_of_1924'),
  ('Q2634783', 'Revolution of 1930', 'The Revolution of 1930 (Portuguese: Revolução de 1930) was an armed insurrection across Brazil that ended the Old Republic. The revolution replaced incumbent president Washington Luís with defeated presidential candidate and revolutionary leader Getúlio Vargas, concluding the political hegemony of a four-decade-old oligarchy and beginning the Vargas Era.', 1930, 10, NULL, NULL, NULL, NULL, 'month', 'October 1930', 52, 'https://en.wikipedia.org/wiki/Revolution_of_1930'),
  ('Q4532311', 'Vargas era', 'In Brazil''s history, the Vargas era (Portuguese: Era Vargas; Portuguese pronunciation: [ˈɛɾɐ ˈvaʁɡɐs]) was the period from 1930 to 1946 when the country was governed by Getúlio Vargas. The period can be subdivided into the Second Brazilian Republic, from 1930 to 1937, and the Third Brazilian Republic, or Estado Novo, from 1937 to 1946.', 1930, 11, 3, 1945, 10, 29, 'day', '3 November 1930 – 29 October 1945', 57, 'https://en.wikipedia.org/wiki/Vargas_era'),
  ('Q2592295', 'Constitutionalist Revolution', 'The Constitutionalist Revolution of 1932 (also known as the Paulista War or Brazilian Civil War) was the uprising by the population of the Brazilian state of São Paulo against the Revolution of 1930, when Getúlio Vargas assumed the nation''s presidency. Vargas was supported by the people, the military and the political elite of Minas Gerais, Rio Grande do Sul and Paraíba.', 1932, NULL, NULL, 1932, 10, 2, 'year', '1932', 51, 'https://en.wikipedia.org/wiki/Constitutionalist_Revolution'),
  ('Q3944397', 'Battle of Collecchio', 'The Battle of Collecchio-Fornovo (26–29 April 1945) was a battle of the Second World War fought between the Brazilian Expeditionary Force (Força Expedicionária Brasileira – FEB) and Italian partisans, with supporting armor attachments from the American 1st Armored and 92nd Infantry Divisions, against the retreating Axis forces of the Wehrmacht''s 148th Infantry Division, 90th Panzergrenadier Division, and the fascist National Republican Army''s 1st Bersaglieri "Italia" and 4th Alpini "Monte Rosa" Divisions. The battle took place around the towns of Collecchio and Fornovo di Taro,…', 1945, 4, 26, 1945, 4, 29, 'day', '26 April 1945 – 29 April 1945', 39, 'https://en.wikipedia.org/wiki/Battle_of_Collecchio'),
  ('Q6143782', 'Pan Am Flight 202', 'Pan American World Airways Flight 202 was a Boeing 377 Stratocruiser aircraft that crashed in the Amazon Basin about 281 nautical miles (320 mi; 520 km) southwest of Carolina, Brazil, on April 29, 1952. The accident happened en route from Rio de Janeiro, Brazil, to Port of Spain, Trinidad and Tobago, during the third leg of a four-leg journey.', 1952, 4, 29, NULL, NULL, NULL, 'day', '29 April 1952', 45, 'https://en.wikipedia.org/wiki/Pan_Am_Flight_202'),
  ('Q10332838', '1955 Brazilian coup d''état', 'The Preventative Coup of November 11, sometimes called the 1955 Brazilian coup d''état or referred to as an "anti-coup" or a "counter-coup" (Portuguese: Novembrada, Movimento de 11 de Novembro, Contragolpe, Golpe Preventivo do Marechal Lott), was a series of military and political events led by Henrique Teixeira Lott that resulted in Nereu Ramos assuming the presidency of Brazil until being peacefully succeeded by Juscelino Kubitschek a few months later. The bloodless coup removed Carlos Luz from the presidency because he was suspected of plotting to prevent Kubitschek from taking office.', 1955, 11, 11, NULL, NULL, NULL, 'day', '11 November 1955', 47, 'https://en.wikipedia.org/wiki/Preventative_Coup_of_November_11'),
  ('Q1370527', 'Brazilian military government (1964–1985)', 'The military dictatorship in Brazil (Portuguese: ditadura militar [dʒitaˈduɾɐ miliˈtaʁ]), sometimes called the Fifth Brazilian Republic, was established on 1 April 1964, after a coup d''état by the Brazilian Armed Forces with support from the United States government against President João Goulart. It lasted 21 years, until 15 March 1985.', 1964, 4, 1, NULL, NULL, NULL, 'day', '1 April 1964', 66, 'https://en.wikipedia.org/wiki/Military_dictatorship_in_Brazil'),
  ('Q4571496', '1964 Brazilian military regime', 'The 1964 Brazilian coup d''état (Portuguese: Golpe de estado no Brasil em 1964) was the overthrow of Brazilian president João Goulart by a military coup from March 31 to April 1, 1964, ending the Fourth Brazilian Republic (1946–1964) and initiating the Brazilian military dictatorship (1964–1985). The coup took the form of a military rebellion, the declaration of vacancy in the presidency by the National Congress on April 2, the formation of a military junta (the Supreme Command of the Revolution) and the exile of the president on April 4.', 1964, 4, 1, NULL, NULL, NULL, 'day', '1 April 1964', 64, 'https://en.wikipedia.org/wiki/1964_Brazilian_coup_d''%C3%A9tat'),
  ('Q953414', 'Joelma fire', 'Edifício Praça da Bandeira, formerly known as the Joelma Building, is a 25-story building in downtown São Paulo, Brazil, completed in 1971, located at Avenida 9 de Julho, 225. On 1 February 1974, an air conditioning unit on the twelfth floor overheated, starting a fire.', 1974, 2, 1, NULL, NULL, NULL, 'day', '1 February 1974', 45, 'https://en.wikipedia.org/wiki/Joelma_Building_fire'),
  ('Q7120079', 'PP-VLU', 'Varig Flight 967 was an international cargo flight from Narita International Airport in Japan to Rio de Janeiro–Galeão International Airport in Brazil, with a stopover at Los Angeles International Airport in the United States. On 30 January 1979, the Boeing 707 serving the flight disappeared while en route to Los Angeles with radio contact being lost an hour into the flight.', 1979, 1, 30, NULL, NULL, NULL, 'day', '30 January 1979', 55, 'https://en.wikipedia.org/wiki/Varig_Flight_967'),
  ('Q7833816', 'Transbrasil Flight 303', 'Transbrasil Flight 303 was a scheduled flight from Congonhas-São Paulo Airport in São Paulo, Brazil, to Hercílio Luz International Airport in Florianópolis, Brazil, on 12 April 1980. The Boeing 727-27C crashed on approach to Hercílio Luz International Airport.', 1980, 4, 12, NULL, NULL, NULL, 'day', '12 April 1980', 47, 'https://en.wikipedia.org/wiki/Transbrasil_Flight_303'),
  ('Q4346080', 'VASP Flight 168', 'VASP Flight 168, a Boeing 727-212 registered PP-SRK, was a scheduled domestic passenger flight from São Paulo to Fortaleza, Brazil which, on June 8, 1982, crashed into a mountainside, while descending into Fortaleza, killing all 137 people on board. The crash of Flight 168 remains both the largest death toll of a Brazilian aircraft accident from the 20th century and the third-highest death toll of any aviation accident in Brazil after Gol Transportes Aéreos Flight 1907 and TAM Airlines Flight 3054.', 1982, 6, 8, NULL, NULL, NULL, 'day', '8 June 1982', 47, 'https://en.wikipedia.org/wiki/VASP_Flight_168'),
  ('Q10392510', 'Transbrasil Flight 801', 'Transbrasil Flight 801 (TR801/TBA801) was a scheduled cargo flight from Eduardo Gomes International Airport to São Paulo/Guarulhos International Airport that crashed on 21 March 1989. The Boeing 707 crashed into a heavily populated slum in Guarulhos 2 kilometres (1.2 mi; 1.1 nmi) from the runway.', 1989, 3, 21, NULL, NULL, NULL, 'day', '21 March 1989', 45, 'https://en.wikipedia.org/wiki/Transbrasil_Flight_801'),
  ('Q2341407', 'Carandiru massacre', 'The Carandiru massacre (Portuguese: Massacre do Carandiru, pronounced [maˈsakɾi du kaɾɐ̃dʒiˈɾu]) occurred on 2 October 1992, in Carandiru Penitentiary in São Paulo, Brazil, when São Paulo''s military police stormed the penitentiary following a prison riot. The massacre, which left 111 prisoners dead, is considered by many people to be a major human rights violation.', 1992, 10, 2, NULL, NULL, NULL, 'day', '2 October 1992', 53, 'https://en.wikipedia.org/wiki/Carandiru_massacre'),
  ('Q81771', 'Candelária massacre', 'The Candelária massacre (Portuguese: chacina da Candelária [ʃɐˈsĩnɐ ðɐ kɐ̃deˈlaɾjɐ]) was a mass killing in Rio de Janeiro, Brazil, on July 23, 1993. During the night, eight homeless people, including six minors, were killed by a group of men beside the Candelária Church.', 1993, 7, 23, NULL, NULL, NULL, 'day', '23 July 1993', 45, 'https://en.wikipedia.org/wiki/Candel%C3%A1ria_massacre'),
  ('Q3177188', 'TAM Transportes Aéreos Regionais Flight 402', 'TAM Transportes Aéreos Regionais Flight 402 was a scheduled domestic flight from Caxias do Sul, Brazil, to Recife International Airport in Recife, via São Paulo–Congonhas International Airport and Santos Dumont Airport in Rio de Janeiro. On 31 October 1996, at 08:27 (UTC-2), the thrust reverser was accidentally deployed on the starboard engine of the Fokker 100 operating the route while the aircraft was climbing away from runway 17R at Congonhas.', 1996, 10, 31, NULL, NULL, NULL, 'day', '31 October 1996', 53, 'https://en.wikipedia.org/wiki/TAM_Transportes_A%C3%A9reos_Regionais_Flight_402'),
  ('Q5354122', 'Eldorado do Carajás massacre', 'The Eldorado do Carajás massacre (Portuguese pronunciation: [mɐˈsakɾi dʒi ɛwdoˈɾadu du kɐɾɐˈʒas]) was the mass killing of 21 landless farmers who were taking part in a peaceful protest. They were shot by military police on April 17, 1996, in the southern region of the Pará state, Brazil.', 1996, 4, 17, NULL, NULL, NULL, 'day', '17 April 1996', 45, 'https://en.wikipedia.org/wiki/Eldorado_do_Caraj%C3%A1s_massacre'),
  ('Q1351598', 'Gol Transportes Aéreos Flight 1907', 'On September 29, 2006, Gol Transportes Aéreos Flight 1907, a Boeing 737-800 on a scheduled domestic passenger flight from Manaus, Amazonas, to Brasília and Rio de Janeiro, collided mid-air with an Embraer Legacy 600 business jet flying on an opposite heading over the Brazilian state of Mato Grosso. The winglet of the Legacy sliced off about half of the 737''s left wing, causing the 737 to break up and crash into an area of dense jungle, killing all 154 passengers and crew on board.', 2006, 9, 29, NULL, NULL, NULL, 'day', '29 September 2006', 60, 'https://en.wikipedia.org/wiki/Gol_Transportes_A%C3%A9reos_Flight_1907'),
  ('Q865870', 'TAM Airlines Flight 3054', 'TAM Airlines Flight 3054 was a regularly scheduled domestic passenger flight operated by TAM Airlines from Porto Alegre to São Paulo, Brazil. On the evening of 17 July 2007, the Airbus A320 serving the flight from Porto Alegre overran runway 35L at São Paulo''s Congonhas Airport after touching down during moderate rain and crashed into a nearby TAM Express warehouse adjacent to a gas station.', 2007, 7, 17, NULL, NULL, NULL, 'day', '17 July 2007', 68, 'https://en.wikipedia.org/wiki/TAM_Airlines_Flight_3054'),
  ('Q2031700', '2008 Santa Catarina floods', 'The 2008 Santa Catarina floods were floods in Santa Catarina, Brazil in November 2008. They occurred after a period of heavy rainfall, most significantly from 20-23 of November.', 2008, 11, NULL, NULL, NULL, NULL, 'month', 'November 2008', 39, 'https://en.wikipedia.org/wiki/2008_Santa_Catarina_floods'),
  ('Q854898', 'January 2011 Rio de Janeiro floods and mudslides', 'A series of floods and mudslides took place in January 2011 in several towns of the Mountainous Region (Região Serrana), in the Brazilian state of Rio de Janeiro. Casualties occurred in the cities of Nova Friburgo, Teresópolis, Petrópolis, Bom Jardim, Sumidouro and São José do Vale do Rio Preto.', 2011, 1, 17, NULL, NULL, NULL, 'day', '17 January 2011', 61, 'https://en.wikipedia.org/wiki/January_2011_Rio_de_Janeiro_floods_and_mudslides'),
  ('Q3750271', 'Kiss nightclub fire', 'On 27 January 2013, 242 people were killed and at least 630 others injured in a fire in the Kiss nightclub in Santa Maria, Rio Grande do Sul, Brazil. The fire started between 2:00 and 2:30 a.m.', 2013, 1, 27, NULL, NULL, NULL, 'day', '27 January 2013', 57, 'https://en.wikipedia.org/wiki/Kiss_nightclub_fire'),
  ('Q13454627', '2013 protests in Brazil', 'The 2013 Brazilian protests were public demonstrations in several Brazilian cities, initiated mainly by the Movimento Passe Livre (Free Fare Movement), a local entity that advocates for free public transportation. The demonstrations were initially organized to protest against increases in bus, train, and metro ticket prices in some Brazilian cities, but grew to include other issues such as the high corruption in the government and police brutality used against some demonstrators.', 2013, 6, NULL, NULL, NULL, NULL, 'month', 'June 2013', 61, 'https://en.wikipedia.org/wiki/2013_protests_in_Brazil'),
  ('Q19595400', '2015 protests in Brazil', 'In 2015 and 2016, a series of protests in Brazil denounced corruption and the government of President Dilma Rousseff, triggered by revelations that numerous politicians allegedly accepted bribes connected to contracts at state-owned energy company Petrobras between 2003 and 2010 and connected to the Workers'' Party, while Rousseff chaired the company''s board of directors. The first protests on 15 March 2015 numbered between one and nearly three million protesters against the scandal and the country''s poor economic situation.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 43, 'https://en.wikipedia.org/wiki/2015%E2%80%9316_protests_in_Brazil'),
  ('Q21686043', '2015–16 Zika virus epidemic', 'An epidemic of Zika fever, caused by Zika virus, began in Brazil and affected other countries in the Americas from April 2015 to November 2016. The World Health Organization (WHO) declared the end of the epidemic in November 2016, but noted that the virus still represents "a highly significant and long term problem".', 2015, 4, NULL, 2016, 11, NULL, 'month', 'April 2015 – November 2016', 64, 'https://en.wikipedia.org/wiki/2015%E2%80%9316_Zika_virus_epidemic'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q83807488', '2020 Brazilian floods and mudslides', 'From 17 to 29 January 2020, heavy rainstorms associated with Subtropical Storm Kurumí caused widespread flooding and landslides in Brazil''s Southeast Region states of Minas Gerais, Espírito Santo and Rio de Janeiro. The state capital of Minas Gerais, Belo Horizonte, reported it was the highest rainfall in over 110 years.', 2020, 1, 17, 2020, 1, 29, 'day', '17 January 2020 – 29 January 2020', 39, 'https://en.wikipedia.org/wiki/2020_Brazilian_floods_and_mudslides'),
  ('Q105063804', '2021 Palmas FR plane crash', 'The 2021 Palmas FR plane crash took place on 24 January 2021, when a private Beechcraft Baron belonging to the Palmas Futebol e Regatas, a Brazilian association football team, crashed on takeoff from Associação Tocantinense de Aviação Aerodrome, a private airfield near Porto Nacional, Tocantins, Brazil. All six people on board were killed: four footballers, the team''s owner, and the pilot.', 2021, 1, 24, NULL, NULL, NULL, 'day', '24 January 2021', 45, 'https://en.wikipedia.org/wiki/2021_Palmas_FR_plane_crash'),
  ('Q109783491', '2021 Amazonas earthquake', 'A major earthquake struck northern Peru on November 28, 2021, 5:52 a.m. local time with a magnitude of 7.5 on the moment magnitude scale between the Amazonas and Loreto departments of Peru.', 2021, 11, 28, NULL, NULL, NULL, 'day', '28 November 2021', 43, 'https://en.wikipedia.org/wiki/2021_Northern_Peru_earthquake'),
  ('Q110291626', 'Late December 2021 Bahia floods', 'Beginning on 24 December 2021, record rainfall across the northeastern Brazilian state Bahia resulted in severe floods, which caused the death of 21 people, injured another 358 and displaced 62,800. In a tweet, Rui Costa, the Governor of Bahia, declared the floods to be "the worst disaster that has ever occurred in the history of Bahia".', 2021, 12, 7, 2022, NULL, NULL, 'day', '7 December 2021 – 2022', 39, 'https://en.wikipedia.org/wiki/Late_December_2021_Bahia_floods'),
  ('Q110485448', 'Capitólio rockfall', 'On 8 January 2022, a rockfall occurred in a canyon of Furnas Lake in Capitólio, Minas Gerais, Brazil. A cliff face collapsed onto tourist pleasure boats on the lake, killing 10 people and leaving 32 others injured.', 2022, 1, 8, NULL, NULL, NULL, 'day', '8 January 2022', 43, 'https://en.wikipedia.org/wiki/Capit%C3%B3lio_rockfall'),
  ('Q110932715', '2022 Petrópolis floods', 'On 15 February 2022, intense rainfall in Petrópolis, Rio de Janeiro, Brazil caused mudslides and flooding that destroyed parts of the city. At least 231 people died in the disaster.', 2022, 2, 15, 2022, 3, 21, 'day', '15 February 2022 – 21 March 2022', 56, 'https://en.wikipedia.org/wiki/2022_Petr%C3%B3polis_floods'),
  ('Q112175496', 'Floods and landslides on the northeast coast of Brazil in 2022', 'Floods and mudslides occurred in the Northeast Region of Brazil in 2022. Its cause was the rains that hit mainly the state of Pernambuco, but also Sergipe, Alagoas, Paraíba and Rio Grande do Norte.', 2022, 5, 27, 2022, 5, 29, 'day', '27 May 2022 – 29 May 2022', 41, 'https://en.wikipedia.org/wiki/2022_Northeastern_Brazil_floods_and_mudslides'),
  ('Q116142348', '2023 Brazilian Congress attack', 'On 8 January 2023, following the defeat of president Jair Bolsonaro in the 2022 Brazilian general election and the inauguration of his successor Luiz Inácio Lula da Silva, a mob of Bolsonaro''s supporters attacked Brazil''s federal government buildings in the capital, Brasília. The mob invaded and caused deliberate damage to the Supreme Federal Court, the National Congress Palace and the Planalto Presidential Palace in the Praça dos Três Poderes (English: Three Powers Square or Three Branches of Government), seeking to violently overthrow the democratically elected president Lula, who had…', 2023, 1, 8, 2023, NULL, NULL, 'day', '2023', 70, 'https://en.wikipedia.org/wiki/8_January_Bras%C3%ADlia_attacks'),
  ('Q116843958', '2023 São Paulo floods and landslides', 'During the 2023 Brazilian Carnival holiday weekend, record-breaking rainfall—reaching 682 mm (26.9 in) in 24 hours—caused deadly floods and landslides across the state of São Paulo. 65 people were killed, of which 64 were in São Sebastião.', 2023, 2, 18, 2023, 2, 19, 'day', '18 February 2023 – 19 February 2023', 39, 'https://en.wikipedia.org/wiki/2023_S%C3%A3o_Paulo_floods_and_landslides'),
  ('Q125772990', '2024 Rio Grande do Sul floods', 'The 2024 Rio Grande do Sul floods were severe floods caused by heavy rains and storms that hit the Brazilian state of Rio Grande do Sul, and the adjacent Uruguayan cities of Treinta y Tres, Paysandú, Cerro Largo, and Salto. From 29 April through to May, it resulted in 181 fatalities (as of 7 July 2024), widespread landslides, and a dam collapse.', 2024, 4, 28, 2024, 5, NULL, 'day', '28 April 2024 – May 2024', 58, 'https://en.wikipedia.org/wiki/2024_Rio_Grande_do_Sul_floods'),
  ('Q128796456', 'Voepass Linhas Aéreas Flight 2283', 'Voepass Flight 2283 was a scheduled domestic Brazilian passenger flight from Cascavel to Guarulhos. On August 9, 2024, the ATR 72 serving the flight crashed in Vinhedo, São Paulo State.', 2024, 8, 9, NULL, NULL, NULL, 'day', '9 August 2024', 65, 'https://en.wikipedia.org/wiki/Voepass_Flight_2283');
